import{_ as t,o as i,c as s,a4 as a}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse('{"title":"4. Installation","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"4. Installation","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/notice/4-installation.md","filePath":"documentation/notice/4-installation.md"}'),n={name:"documentation/notice/4-installation.md"};function o(r,e,l,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="4-installation" tabindex="-1">4. Installation <a class="header-anchor" href="#4-installation" aria-label="Permalink to &quot;4. Installation {#4-installation}&quot;">​</a></h1><p>Il existe deux façons d&#39;installer Teuthis-CMS, selon le besoin.</p><h2 id="41-essayer-rapidement-api-seule" tabindex="-1">4.1 Essayer rapidement (API seule) <a class="header-anchor" href="#41-essayer-rapidement-api-seule" aria-label="Permalink to &quot;4.1 Essayer rapidement (API seule) {#41-essayer-rapidement-api-seule}&quot;">​</a></h2><p>Cette méthode installe uniquement le moteur (l&#39;API), sans l&#39;interface d&#39;administration graphique — utile pour un premier essai technique ou une intégration.</p><p><strong>Prérequis</strong> : Python 3.12 ou plus récent, et Docker installé et démarré (le CMS a besoin d&#39;une base de données PostgreSQL, que cette commande démarre automatiquement dans un conteneur).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">pip</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> install</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis-cms</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">teuthiscms</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> mon-site</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;">cd</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> mon-site</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">python</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -m</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> manage</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> runserver</span></span></code></pre></div><p>Cette suite de commandes :</p><ol><li>installe le logiciel ;</li><li>crée un nouveau projet nommé <code>mon-site</code>, démarre sa base de données et applique les mises à jour de structure nécessaires ;</li><li>démarre le serveur, accessible sur <code>http://localhost:8000</code> (la documentation technique des points d&#39;entrée est visible sur <code>/docs</code>).</li></ol><p>L&#39;organisation et son site principal sont créés automatiquement à cette étape. L&#39;identifiant de l&#39;organisation s&#39;affiche à l&#39;écran et dans un fichier <code>README.md</code> généré dans le dossier du projet — il servira à créer le premier compte administrateur (voir <a href="/teuthis-cms-distribution/documentation/notice/5-configuration#51-premier-compte-administrateur">§5.1</a>).</p><p>Si le port 5432 (utilisé par la base de données) est déjà occupé sur la machine : <code>teuthiscms mon-site --db-port 5433</code>.</p><h2 id="42-installation-complète-api--interface-dadministration" tabindex="-1">4.2 Installation complète (API + interface d&#39;administration) <a class="header-anchor" href="#42-installation-complète-api--interface-dadministration" aria-label="Permalink to &quot;4.2 Installation complète (API + interface d&#39;administration) {#42-installation-complète-api--interface-dadministration}&quot;">​</a></h2><p>Cette méthode démarre l&#39;ensemble : le moteur, l&#39;interface graphique du back-office, l&#39;ordonnanceur des tâches automatiques (<a href="/teuthis-cms-distribution/documentation/notice/6-exploitation-courriels-anti-robot-taches-automatiques#63-faire-tourner-les-tâches-automatiques">§6.3</a>), et les services nécessaires (base de données, boîte aux lettres de test).</p><p><strong>Prérequis</strong> : avoir cloné le dépôt du projet, et Docker installé et démarré.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">docker</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> compose</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> up</span></span></code></pre></div><p>Une fois démarré :</p><ul><li>Back-office (interface graphique) : <code>http://localhost:3000</code></li><li>API : <code>http://localhost:8000</code></li><li>Boîte aux lettres de test : <code>http://localhost:8025</code></li></ul><p>Cette installation locale est configurée pour fonctionner immédiatement, sans rien renseigner et sans rien envoyer à l&#39;extérieur : les courriels partent dans la boîte aux lettres de test (aucun ne sort de la machine), et la protection anti-robot des formulaires est <code>altcha</code>, qui ne contacte aucun service tiers. Ces deux commodités sont propres au développement — une installation réelle renseigne son propre relais de messagerie et choisit sa propre protection (<a href="/teuthis-cms-distribution/documentation/notice/6-exploitation-courriels-anti-robot-taches-automatiques#6-exploitation--courriels-anti-robot-tâches-automatiques">§6</a>).</p><p><strong>Pour changer un réglage, créez le fichier <code>apps/api/.env</code>.</strong> Recopiez-y <code>apps/api/.env.example</code> et <strong>décommentez seulement les lignes que vous renseignez</strong>. Chaque variable que vous y écrivez remplace la valeur de développement correspondante (fichier <code>apps/api/.env.compose</code>), et une variable absente garde cette valeur. Attention : une ligne <strong>vide</strong> est une décision — <code>SMTP_HOST=</code> coupe les courriels, <code>CAPTCHA_PROVIDER=</code> ferme les formulaires publics. Redémarrez ensuite l&#39;API et l&#39;ordonnanceur : <code>docker compose up -d cms-api cms-scheduler</code>.</p><p>Aucun fournisseur d&#39;intelligence artificielle n&#39;est requis ni démarré par défaut. Pour développer ou tester les fonctions IA avec un modèle exécuté localement (sans envoyer de données à l&#39;extérieur) :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">docker</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> compose</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> --profile</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> ai-local</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> up</span></span></code></pre></div><h2 id="43-déploiement-en-production" tabindex="-1">4.3 Déploiement en production <a class="header-anchor" href="#43-déploiement-en-production" aria-label="Permalink to &quot;4.3 Déploiement en production {#43-déploiement-en-production}&quot;">​</a></h2><p>Pour une instance réelle, en HTTPS, avec les images publiées sur GHCR plutôt qu&#39;une reconstruction locale : voir <a href="/teuthis-cms-distribution/documentation/referent/"><code>deploy/LISEZMOI.md</code></a>. Cette pile ajoute un frontal HTTPS automatique (Caddy), une base de données sans port publié, et les modules facultatifs (antivirus, extraction documentaire, IA locale) en profils Docker Compose séparés (ADR-0045).</p><p>Sur un serveur Debian 12 ou Ubuntu 22.04/24.04, un installateur fait tout en une commande — vérifications du serveur et du DNS, Docker, secrets, HTTPS — puis affiche l&#39;adresse de l&#39;écran d&#39;installation et la clé à y saisir : <code>sudo sh installer.sh --profil &lt;votre profil&gt;</code>, après l&#39;avoir téléchargé depuis la release et avoir vérifié sa somme (voir <a href="/teuthis-cms-distribution/installer/guide-pas-a-pas#installation-guidée">« Installation guidée »</a>).</p>`,23)])])}const m=t(n,[["render",o]]);export{h as __pageData,m as default};
